import 'dart:convert';

import 'rates.dart';

class CurrencyResponse {
	String? result;
	String? provider;
	String? documentation;
	String? termsOfUse;
	int? timeLastUpdateUnix;
	String? timeLastUpdateUtc;
	int? timeNextUpdateUnix;
	String? timeNextUpdateUtc;
	int? timeEolUnix;
	String? baseCode;
	Rates? rates;

	CurrencyResponse({
		this.result, 
		this.provider, 
		this.documentation, 
		this.termsOfUse, 
		this.timeLastUpdateUnix, 
		this.timeLastUpdateUtc, 
		this.timeNextUpdateUnix, 
		this.timeNextUpdateUtc, 
		this.timeEolUnix, 
		this.baseCode, 
		this.rates, 
	});

	factory CurrencyResponse.from(Map<String, dynamic> data) {
		return CurrencyResponse(
			result: data['result'] as String?,
			provider: data['provider'] as String?,
			documentation: data['documentation'] as String?,
			termsOfUse: data['terms_of_use'] as String?,
			timeLastUpdateUnix: data['time_last_update_unix'] as int?,
			timeLastUpdateUtc: data['time_last_update_utc'] as String?,
			timeNextUpdateUnix: data['time_next_update_unix'] as int?,
			timeNextUpdateUtc: data['time_next_update_utc'] as String?,
			timeEolUnix: data['time_eol_unix'] as int?,
			baseCode: data['base_code'] as String?,
			rates: data['rates'] == null
						? null
						: Rates.(data['rates'] as Map<String, dynamic>),
		);
	}



	Map<String, dynamic> () {
		return {
			'result': result,
			'provider': provider,
			'documentation': documentation,
			'terms_of_use': termsOfUse,
			'time_last_update_unix': timeLastUpdateUnix,
			'time_last_update_utc': timeLastUpdateUtc,
			'time_next_update_unix': timeNextUpdateUnix,
			'time_next_update_utc': timeNextUpdateUtc,
			'time_eol_unix': timeEolUnix,
			'base_code': baseCode,
			'rates': rates?.(),		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [CurrencyResponse].
	factory CurrencyResponse.fromJson(String data) {
		return CurrencyResponse.from(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [CurrencyResponse] to a JSON string.
	String toJson() => json.encode(());
}
